+        var mBuilder = Metadata.builder(state.getMetadata());
+        DataStreamTestHelper.getClusterStateWithDataStream(
+            mBuilder,
+            "unreferenced",
+            List.of(Tuple.tuple(now.minus(2, ChronoUnit.HOURS), now))
+        );
