+    public void testExportsQualifiedExportMismatch() {
+        var exports = createExports("p", Set.of("m"));
+        assertMismatch(exports, exportsOf("p.foo", Set.of("mod")), equalTo("Exports[p.foo to [mod]], actual Exports[p to [m]]"));
