+        Optional<Map<Node, Integer>> assignments = plan.assignments(m);
+        assertThat(assignments.isPresent(), is(true));
+        assertThat(assignments.get().size(), equalTo(1));
+        assertThat(assignments.get().get(n), equalTo(m.allocations()));
