+        AssignmentPlan binPackingPlan = weightsAndBinPackingPlan.v2();
+        if (binPackingPlan.compareTo(assignmentPlan) > 0) {
+            assignmentPlan = binPackingPlan;
+            logger.debug(() -> "Best plan is from bin packing");
+        } else {
